button.code:
row(vec![
    Button::new("button-pending")
        .is_pending(true)
        .content(move |state| {
            gpui::div()
                .flex()
                .items_center()
                .gap(px(8.))
                .when(state.is_pending, |content| {
                    content.child(
                        Spinner::new("button-pending-spinner")
                            .size(SpinnerSize::Sm)
                            .current_color(pending_foreground),
                    )
                })
                .child(if state.is_pending {
                    "Uploading"
                } else {
                    "Upload"
                })
                .into_any_element()
        })
        .into_any_element(),
    Button::new("button-disabled")
        .label("Disabled")
        .is_disabled(true)
        .into_any_element(),
])

