use gpui::prelude::*;
use gpui::px;

close-button.code:
{
    let muted = cx.colors().muted;
    let foreground = cx.colors().foreground;
    gpui::div()
        .flex()
        .flex_col()
        .items_start()
        .gap(px(12.))
        .children(vec![CloseButton::new("close-button-render-state")
                .content(move |state| {
                    gpui::svg()
                        .size(px(16.))
                        .path(if state.is_pressed {
                            icons::CLOSE_CIRCLE
                        } else {
                            icons::CLOSE
                        })
                        .text_color(if state.is_disabled {
                            muted
                        } else if state.is_hovered || state.is_focused {
                            foreground
                        } else {
                            muted
                        })
                        .into_any_element()
                })
                .into_any_element()])
}

