toggle-button.code:
gpui::div()
    .flex()
    .flex_col()
    .items_start()
    .gap(px(12.))
    .children(vec![
        ToggleButton::new("toggle-button-like")
            .label(if liked { "Liked" } else { "Like" })
            .is_selected(liked)
            .child(gpui::svg()
                       .size(px(16.))
                       .path(if liked {
                                   icons::HEART_FILL
                               } else {
                                   icons::HEART
                               })
                       .text_color(cx.colors().foreground))
            .on_change(bool_cb(cx.listener(|this, v: &bool, _, cx| {
                this.toggle_like = *v;
                cx.notify();
            })))
            .into_any_element(),
        para(
            if liked {
                "Status: selected"
            } else {
                "Status: not selected"
            },
            cx,
        ),
    ])

ToggleButtonGroup::new("toggle-button-single")
    .selection_mode(SelectionMode::Single)
    .separators(true)
    .selected_keys(single.into_iter().collect::<Vec<_>>())
    .child_toggle(ToggleButton::new("toggle-button-left").key("left").label("Left"))
    .child_toggle(
        ToggleButton::new("toggle-button-center")
            .key("center")
            .label("Center"),
    )
    .child_toggle(ToggleButton::new("toggle-button-right").key("right").label("Right"))
    .on_selection_change(cx.listener(|this, keys: &[SharedString], _, cx| {
        this.toggle_single = keys.first().cloned();
        cx.notify();
    }))

ToggleButtonGroup::new("toggle-button-multiple")
    .selection_mode(SelectionMode::Multiple)
    .separators(true)
    .selected_keys(multiple.iter().cloned().collect::<Vec<_>>())
    .child_toggle(ToggleButton::new("toggle-button-bold").key("bold").label("Bold"))
    .child_toggle(
        ToggleButton::new("toggle-button-italic")
            .key("italic")
            .label("Italic"),
    )
    .child_toggle(
        ToggleButton::new("toggle-button-underline")
            .key("underline")
            .label("Underline"),
    )
    .on_change(cx.listener(|this, keys: &[SharedString], _, cx| {
        this.toggle_multiple = keys.iter().cloned().collect();
        cx.notify();
    }))

ToggleButtonGroup::new("toggle-button-without-separator")
    // v3: omit the `<ToggleButtonGroup.Separator />` child
    // composition — the port's default draws no dividers.
    .child_toggle(ToggleButton::new("toggle-button-1").label("One"))
    .child_toggle(ToggleButton::new("toggle-button-2").label("Two"))
    .child_toggle(ToggleButton::new("toggle-button-3").label("Three"))

