dropdown.code:
Dropdown::uncontrolled(
        "dd-render-props-dd",
        Button::new("dropdown-render-props")
            .label("Render state")
            .variant(Variant::Secondary),
        vec![
            MenuItem::new("name", "Name"),
            MenuItem::new("date", "Date"),
            MenuItem::new("size", "Size"),
        ],
    )
    .selection_mode(SelectionMode::Multiple)
    .default_selected_keys([SharedString::from("name")])
    .item_content(|key, state| {
