tag-group.code:
gpui::div()
    .flex()
    .flex_col()
    .items_start()
    .gap(px(12.))
    .children(vec![
        TagGroup::new("tag-group-remove-button", tags())
            .label("Skills")
            .on_remove(cx.listener(
                |this, keys: &HashSet<SharedString>, _, cx| {
                    this.tags.retain(|key| !keys.contains(key));
                    this.tag_selection.retain(|key| !keys.contains(key));
                    cx.notify();
                },
            )),
        {
            let custom_tags: Vec<Tag> = tags()
                .into_iter()
                .map(|tag| {
                    tag.remove_content(|| {
                        gpui::div().child("−").into_any_element()
                    })
                })
                .collect();
            TagGroup::new("tag-group-custom-remove-button", custom_tags)
                .label("Skills")
                .on_remove(cx.listener(
                    |this, keys: &HashSet<SharedString>, _, cx| {
                        this.tags.retain(|key| !keys.contains(key));
                        this.tag_selection.retain(|key| !keys.contains(key));
                        cx.notify();
                    },
                ))
        },
    ])

TagGroup::new("tag-group-remove", tags())
    .label("Team")
    .description("Remove a tag to see the group update.")
    .empty_state("All tags removed")
    .on_remove(cx.listener(|this, keys: &HashSet<SharedString>, _, cx| {
        this.tags.retain(|key| !keys.contains(key));
        this.tag_selection.retain(|key| !keys.contains(key));
        cx.notify();
    }))

