                        gpui::div().child("Tech Lead").into_any_element(),
                        gpui::div().child("Paused").into_any_element(),
                    ])
                    .on_resize_start(cx.listener(|this, _, _, cx| {
                        this.set_demo_text_value(
                            "tbl-resize-status",
