range-calendar.code:
gpui::div()
    .flex()
    .flex_col()
    .items_start()
    .gap(px(12.))
    .children({
        let blocked_ranges = [
            (add_days(&today, 2), add_days(&today, 5)),
            (add_days(&today, 12), add_days(&today, 13)),
        ];
        vec![
            RangeCalendar::new(self.demo_range("rc-unavailable", cx))
                .default_value((add_days(&today, 6), add_days(&today, 9)))
                .first_day_of_week(Weekday::Mon)
                .is_date_unavailable(move |date, _| {
                    let date = days_from_civil(&date);
                    blocked_ranges.iter().any(|(start, end)| {
                        date >= days_from_civil(start)
                            && date <= days_from_civil(end)
                    })
                })
                .into_any_element(),
            gpui::div()
                .child("Some days are unavailable")
                .into_any_element(),
        ]
    })

RangeCalendar::new(self.demo_range("rc-anchor", cx))
    .is_date_unavailable(|date, anchor| {
        anchor.is_some_and(|anchor| {
            (date.year, date.month, date.day)
                < (anchor.year, anchor.month, anchor.day)
        })
    })

