popover.code:
gpui::div()
        .relative()
        .flex()
        .flex_wrap()
        .gap(px(24.))
    .children(
        [
            ("po-pl-top", "Top", PopoverPlacement::Top),
            ("po-pl-bottom", "Bottom", PopoverPlacement::Bottom),
            ("po-pl-left", "Left", PopoverPlacement::Left),
            ("po-pl-right", "Right", PopoverPlacement::Right),
        ]
        .into_iter()
        .map(|(id, label, placement)| {
            let open = self.demo_overlay(id);
            let mut placement_slot = gpui::div()
                .relative()
                .flex()
                .flex_col()
                .items_start();
            if open && matches!(placement, PopoverPlacement::Top) {
                placement_slot = placement_slot.pt(px(96.));
            }
            if open
                && matches!(
                    placement,
                    PopoverPlacement::Top | PopoverPlacement::Left
                )
            {
                placement_slot = placement_slot.pl(px(104.));
            }
            overlay_min_h(placement_slot, open, 260.).child(
                Popover::new(
                    Button::new(format!("{id}-trigger"))
                        .label(label)
                        .variant(Variant::Secondary)
                        .size(Size::Sm),
                )
                .id(id)
                .is_open(open)
                .on_open_change(bool_cb(cx.listener(
                    move |this, open: &bool, _, cx| {
                        set_popover_open(
                            &mut this.popover_open,
                            &mut this.demo_flags,
                            id,
                            *open,
                        );
                        cx.notify();
                    },
                )))
                .placement(placement)
                .title(label)
            .child(gpui::div().child("Anchored to its trigger.")),
            )
        }),
    )

