autocomplete.code:
Autocomplete::new(self.demo_text("ac-custom", "", cx), language_items())
    .label("Languages")
    .placeholder("Select languages")
    .selection_mode(SelectionMode::Multiple)
    .default_value(["rust", "go"])
    .value_content(|value| {
        if value.is_placeholder {
            return value.default_children;
        }
        // v3's own example draws the selection as a
        // `TagGroup` of `Tag`s, which is what a
        // multiple-selection trigger looks like there.
        TagGroup::new(
            "autocomplete-custom-tags",
            value
                .selected_items
                .iter()
                .map(|item| Tag::new(item.clone(), item.clone()))
                .collect(),
        )
        .size(Size::Sm)
        .into_any_element()
    })

